// twin-ap-v3: fused side output of a twin step on AArch64 (generated by gen_side_fused.py).
// Computes y' = y(P - G) = mu (x' - x1) - y1, mu = (y1 + y2) i, x' = mu^2 - x1 - x2, i = 1/(x2 - x1),
// in blst's Montgomery representation (R = 2^384), for P = (x1, y1), G = (x2, y2) with x1, y1, x2, y2, i in [0, p).
// The four field routines after the driver are verbatim copies of blst's private AArch64 routines
// __mul_mont_384, __sqr_384, __mul_by_1_mont_384 and __redc_tail_mont_384 (supranational/blst at
// f7a88067ed98385ebc6cf41ccecf21ead706a5b7, build/elf/mul_mont_384-armv8.S, Apache-2.0), renamed with a tw prefix and __SIZEOF_POINTER__ written as 8,
// except that the three result stores at the end of __redc_tail_mont_384 are dropped (its result stays in x11..x16).
// The driver keeps operands in registers between them: one prologue, the modulus loaded twice (__sqr_384 overwrites x5..x10), the additions and
// subtractions inline, and only mu and the 768-bit square on the stack.
//
// Lazy reduction (proof.md Section 2): t = y1 + y2 is left in [0, 2p) and w = mu^2 + 3p - 2 x1 - x2 in [0, 4p);
// both are inputs a of the word-serial Montgomery multiplication __mul_mont_384 with b < p, for which the result
// before its final conditional subtraction is below a b / R + p < 4p^2/R + p < 2p (4p < 2^383 < R), so the single
// conditional subtraction returns the fully reduced product. y' is fully reduced into [0, p) by the last
// (modular) subtraction.
//
// C prototype: void tw_side_fused(limb_t out[12], const limb_t P[12], const limb_t G[12],
//                                 const limb_t inv[6], const limb_t p_and_3p[12], limb_t n0);
// p_and_3p = p followed by 3p (both < 2^384); only out[6..12) = y' is written.
.text
.globl	tw_side_fused
.type	tw_side_fused,%function
.align	5
tw_side_fused:
	stp	x29,x30,[sp,#-128]!
	add	x29,sp,#0
	stp	x19,x20,[sp,#16]
	stp	x21,x22,[sp,#32]
	stp	x23,x24,[sp,#48]
	stp	x25,x26,[sp,#64]
	stp	x27,x28,[sp,#80]
	stp	x5,x0,[sp,#96]		// n0 where tw__mul_mont_384 reads it; out pointer
	str	x4,[sp,#112]		// pointer to p, 3p
	sub	sp,sp,#160		// [sp,0..96) square, [sp,96..144) mu, [sp,144..160) P, G
	stp	x1,x2,[sp,#144]
	mov	x17,x3
	ldp	x5,x6,[x4,#0]
	ldp	x7,x8,[x4,#16]
	ldp	x9,x10,[x4,#32]
// t = y1 + y2 in [0, 2p) (no reduction)
	ldp	x11,x12,[x1,#48]
	ldp	x19,x20,[x2,#48]
	ldp	x13,x14,[x1,#64]
	ldp	x21,x22,[x2,#64]
	ldp	x15,x16,[x1,#80]
	ldp	x23,x24,[x2,#80]
	adds	x11,x11,x19
	adcs	x12,x12,x20
	adcs	x13,x13,x21
	adcs	x14,x14,x22
	adcs	x15,x15,x23
	adcs	x16,x16,x24
// mu = t i, fully reduced
	mov	x2,x17
	ldr	x17,[x2]
	ldr	x4,[x29,#96]
	bl	tw__mul_mont_384
	stp	x11,x12,[sp,#96]
	stp	x13,x14,[sp,#112]
	stp	x15,x16,[sp,#128]
// mu^2, fully reduced
	mov	x0,sp
	bl	tw__sqr_384
	ldr	x2,[x29,#112]
	ldp	x5,x6,[x2,#0]
	ldp	x7,x8,[x2,#16]
	ldp	x9,x10,[x2,#32]
	ldr	x4,[x29,#96]
	mov	x1,sp
	bl	tw__mul_by_1_mont_384
	bl	tw__redc_tail_mont_384
// w = mu^2 + 3p - x1 - x1 - x2 in [0, 4p): every partial value stays in [0, 4p), no borrow or carry out
	ldr	x2,[x29,#112]
	ldp	x19,x20,[x2,#48]
	ldp	x21,x22,[x2,#64]
	ldp	x23,x24,[x2,#80]
	adds	x11,x11,x19
	adcs	x12,x12,x20
	adcs	x13,x13,x21
	adcs	x14,x14,x22
	adcs	x15,x15,x23
	adcs	x16,x16,x24
	ldr	x1,[sp,#144]
	ldp	x19,x20,[x1,#0]
	ldp	x21,x22,[x1,#16]
	ldp	x23,x24,[x1,#32]
	subs	x11,x11,x19
	sbcs	x12,x12,x20
	sbcs	x13,x13,x21
	sbcs	x14,x14,x22
	sbcs	x15,x15,x23
	sbcs	x16,x16,x24
	subs	x11,x11,x19
	sbcs	x12,x12,x20
	sbcs	x13,x13,x21
	sbcs	x14,x14,x22
	sbcs	x15,x15,x23
	sbcs	x16,x16,x24
	ldr	x2,[sp,#152]
	ldp	x19,x20,[x2,#0]
	ldp	x21,x22,[x2,#16]
	ldp	x23,x24,[x2,#32]
	subs	x11,x11,x19
	sbcs	x12,x12,x20
	sbcs	x13,x13,x21
	sbcs	x14,x14,x22
	sbcs	x15,x15,x23
	sbcs	x16,x16,x24
// mu w, fully reduced
	add	x2,sp,#96
	ldr	x17,[x2]
	ldr	x4,[x29,#96]
	bl	tw__mul_mont_384
// y' = mu w - y1 mod p, in [0, p)
	ldr	x1,[sp,#144]
	ldp	x19,x20,[x1,#48]
	ldp	x21,x22,[x1,#64]
	ldp	x23,x24,[x1,#80]
	subs	x11,x11,x19
	sbcs	x12,x12,x20
	sbcs	x13,x13,x21
	sbcs	x14,x14,x22
	sbcs	x15,x15,x23
	sbcs	x16,x16,x24
	sbc	x3,xzr,xzr
	and	x25,x5,x3
	and	x26,x6,x3
	and	x27,x7,x3
	and	x28,x8,x3
	and	x0,x9,x3
	and	x1,x10,x3
	adds	x11,x11,x25
	adcs	x12,x12,x26
	adcs	x13,x13,x27
	adcs	x14,x14,x28
	adcs	x15,x15,x0
	adc	x16,x16,x1
	ldr	x0,[x29,#104]
	stp	x11,x12,[x0,#48]
	stp	x13,x14,[x0,#64]
	stp	x15,x16,[x0,#80]
	add	sp,sp,#160
	ldp	x19,x20,[x29,#16]
	ldp	x21,x22,[x29,#32]
	ldp	x23,x24,[x29,#48]
	ldp	x25,x26,[x29,#64]
	ldp	x27,x28,[x29,#80]
	ldp	x29,x30,[sp],#128
	ret
.size	tw_side_fused,.-tw_side_fused

